package com.mana.brain

import org.junit.Assert.assertEquals
import org.junit.Test

/**
 * Compile-time contract test: these classes are generated by the Android AIDL compiler
 * from system/mana/brain/aidl, the same source directory used by Soong.
 */
class AidlContractCompileTest {
    @Test
    fun generatedBinderAndParcelableTypesArePresent() {
        assertEquals("com.mana.brain.BrainRequest", BrainRequest::class.java.name)
        assertEquals("com.mana.brain.BrainResponse", BrainResponse::class.java.name)
        assertEquals("com.mana.brain.IBrainService", IBrainService::class.java.name)
        assertEquals("com.mana.brain.IBrainCallback", IBrainCallback::class.java.name)
    }
}
